// Concatenates sql/migrations/*.sql (in order) into sql/schema.sql: one paste for a fresh database.
// Every migration is idempotent, so pasting the full file on an existing database is also safe.
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'sql', 'migrations');
const files = fs.readdirSync(dir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();
fs.writeFileSync(
  path.join(__dirname, '..', 'sql', 'schema.sql'),
  '-- GENERATED by scripts/build-schema.js from sql/migrations. Do not edit; add a migration instead.\n\n' +
    files.map((f) => `-- ===== ${f} =====\n${fs.readFileSync(path.join(dir, f), 'utf8')}`).join('\n'),
);
console.log(`sql/schema.sql built from ${files.length} migration(s): ${files.join(', ')}`);
